3.1 Setup y Configuración
// src/api/ordersApi.ts
import axios from 'axios';

const API_BASE_URL = 'http://localhost:8000/api';

const ordersApi = axios.create({
  baseURL: `${API_BASE_URL}/pedidos/`,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Interceptor para agregar token JWT
ordersApi.interceptors.request.use((config) =&gt; {
  const token = localStorage.getItem('access_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export default ordersApi;

3.2 1. Crear Pedido
// src/hooks/useCreateOrder.ts
import { useState } from 'react';
import ordersApi from '../api/ordersApi';

export const useCreateOrder = () =&gt; {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState&lt;string | null&gt;(null);

  const createOrder = async (orderData: {
    tipo_entrega: 'TIENDA' | 'DOMICILIO';
    detalles: Array&lt;{
      producto_id: number;
      cantidad: number;
    }&gt;;
  }) =&gt; {
    setLoading(true);
    setError(null);

    try {
      const response = await ordersApi.post('/', orderData);
      return response.data;
    } catch (err: any) {
      const errorMsg =
        err.response?.data?.detalles?.[0] ||
        err.response?.data?.detail ||
        'Error al crear la orden';
      setError(errorMsg);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  return { createOrder, loading, error };
};

3.2.1 Component: Crear Pedido
// src/components/CreateOrderForm.tsx
import React, { useState } from 'react';
import { useCreateOrder } from '../hooks/useCreateOrder';
import { useCart } from '../hooks/useCart';

export const CreateOrderForm: React.FC = () =&gt; {
  const { createOrder, loading, error } = useCreateOrder();
  const { cartItems, total, clear: clearCart } = useCart();
  const [tipoEntrega, setTipoEntrega] = useState&lt;'TIENDA' | 'DOMICILIO'&gt;('TIENDA');
  const [successMessage, setSuccessMessage] = useState('');

  const handleSubmit = async (e: React.FormEvent) =&gt; {
    e.preventDefault();

    if (cartItems.length === 0) {
      alert('El carrito está vacío');
      return;
    }

    try {
      const orderData = {
        tipo_entrega: tipoEntrega,
        detalles: cartItems.map((item) =&gt; ({
          producto_id: item.id,
          cantidad: item.quantity,
        })),
      };

      const response = await createOrder(orderData);

      setSuccessMessage(
        `✅ Orden ${response.numero_pedido} creada exitosamente`
      );
      clearCart();
      setTipoEntrega('TIENDA');

      // Redirigir después de 2 segundos
      setTimeout(() =&gt; {
        window.location.href = `/orders/${response.id}`;
      }, 2000);
    } catch (err) {
      console.error('Error creating order:', err);
    }
  };

  return (
    &lt;form onSubmit={handleSubmit} className="order-form"&gt;
      &lt;h2&gt;Confirmar Pedido&lt;/h2&gt;

      {error && &lt;div className="error"&gt;{error}&lt;/div&gt;}
      {successMessage && &lt;div className="success"&gt;{successMessage}&lt;/div&gt;}

      &lt;div className="form-group"&gt;
        &lt;label htmlFor="delivery"&gt;Tipo de Entrega:&lt;/label&gt;
        &lt;select
          id="delivery"
          value={tipoEntrega}
          onChange={(e) =&gt;
            setTipoEntrega(e.target.value as 'TIENDA' | 'DOMICILIO')
          }
          disabled={loading}
        &gt;
          &lt;option value="TIENDA"&gt;Recoger en Tienda&lt;/option&gt;
          &lt;option value="DOMICILIO"&gt;Entrega a Domicilio&lt;/option&gt;
        &lt;/select&gt;
      &lt;/div&gt;

      &lt;div className="cart-summary"&gt;
        &lt;p&gt;Total: ${total.toFixed(2)}&lt;/p&gt;
        &lt;p&gt;Número de items: {cartItems.length}&lt;/p&gt;
      &lt;/div&gt;

      &lt;button type="submit" disabled={loading}&gt;
        {loading ? 'Creando orden...' : 'Crear Orden'}
      &lt;/button&gt;
    &lt;/form&gt;
  );
};

3.3 2. Listar Órdenes del Usuario
// src/hooks/useOrdersList.ts
import { useEffect, useState } from 'react';
import ordersApi from '../api/ordersApi';

export interface Order {
  id: number;
  numero_pedido: string;
  estado: string;
  tipo_entrega: string;
  total: string;
  fecha_creacion: string;
  cliente_nombre: string;
}

export const useOrdersList = (filters?: { estado?: string; search?: string }) =&gt; {
  const [orders, setOrders] = useState&lt;Order[]&gt;([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState&lt;string | null&gt;(null);

  useEffect(() =&gt; {
    const fetchOrders = async () =&gt; {
      setLoading(true);
      setError(null);

      try {
        const params = new URLSearchParams();
        if (filters?.estado) params.append('estado', filters.estado);
        if (filters?.search) params.append('search', filters.search);
        params.append('ordering', '-fecha_creacion');

        const response = await ordersApi.get('/', { params });
        setOrders(response.data.results);
      } catch (err: any) {
        setError(
          err.response?.data?.detail ||
          'Error al cargar las órdenes'
        );
      } finally {
        setLoading(false);
      }
    };

    fetchOrders();
  }, [filters?.estado, filters?.search]);

  return { orders, loading, error };
};

3.3.1 Component: Listar Órdenes
// src/components/OrdersList.tsx
import React, { useState } from 'react';
import { useOrdersList } from '../hooks/useOrdersList';

const ESTADO_COLORS = {
  RECIBIDO: '#3498db',
  PREPARACION: '#f39c12',
  LISTO: '#2ecc71',
  ENTREGADO: '#27ae60',
  CANCELADO: '#e74c3c',
};

export const OrdersList: React.FC = () =&gt; {
  const [estadoFilter, setEstadoFilter] = useState&lt;string | undefined&gt;(undefined);
  const [searchTerm, setSearchTerm] = useState('');
  const { orders, loading, error } = useOrdersList({
    estado: estadoFilter,
    search: searchTerm,
  });

  if (loading) return &lt;div className="loading"&gt;Cargando órdenes...&lt;/div&gt;;
  if (error) return &lt;div className="error"&gt;{error}&lt;/div&gt;;

  return (
    &lt;div className="orders-container"&gt;
      &lt;h2&gt;Mis Órdenes&lt;/h2&gt;

      &lt;div className="filters"&gt;
        &lt;input
          type="text"
          placeholder="Buscar por número de pedido"
          value={searchTerm}
          onChange={(e) =&gt; setSearchTerm(e.target.value)}
          className="search-input"
        /&gt;

        &lt;select
          value={estadoFilter || ''}
          onChange={(e) =&gt; setEstadoFilter(e.target.value || undefined)}
          className="filter-select"
        &gt;
          &lt;option value=""&gt;Todos los estados&lt;/option&gt;
          &lt;option value="RECIBIDO"&gt;Recibido&lt;/option&gt;
          &lt;option value="PREPARACION"&gt;En preparación&lt;/option&gt;
          &lt;option value="LISTO"&gt;Listo&lt;/option&gt;
          &lt;option value="ENTREGADO"&gt;Entregado&lt;/option&gt;
          &lt;option value="CANCELADO"&gt;Cancelado&lt;/option&gt;
        &lt;/select&gt;
      &lt;/div&gt;

      {orders.length === 0 ? (
        &lt;div className="no-orders"&gt;No hay órdenes para mostrar&lt;/div&gt;
      ) : (
        &lt;table className="orders-table"&gt;
          &lt;thead&gt;
            &lt;tr&gt;
              &lt;th&gt;Número&lt;/th&gt;
              &lt;th&gt;Estado&lt;/th&gt;
              &lt;th&gt;Total&lt;/th&gt;
              &lt;th&gt;Tipo Entrega&lt;/th&gt;
              &lt;th&gt;Fecha&lt;/th&gt;
              &lt;th&gt;Acción&lt;/th&gt;
            &lt;/tr&gt;
          &lt;/thead&gt;
          &lt;tbody&gt;
            {orders.map((order) =&gt; (
              &lt;tr key={order.id}&gt;
                &lt;td className="order-number"&gt;{order.numero_pedido}&lt;/td&gt;
                &lt;td&gt;
                  &lt;span
                    className="status-badge"
                    style={{
                      backgroundColor:
                        ESTADO_COLORS[
                          order.estado as keyof typeof ESTADO_COLORS
                        ],
                    }}
                  &gt;
                    {order.estado}
                  &lt;/span&gt;
                &lt;/td&gt;
                &lt;td&gt;${parseFloat(order.total).toFixed(2)}&lt;/td&gt;
                &lt;td&gt;{order.tipo_entrega === 'TIENDA' ? '🏪' : '🚚'}&lt;/td&gt;
                &lt;td&gt;
                  {new Date(order.fecha_creacion).toLocaleDateString()}
                &lt;/td&gt;
                &lt;td&gt;
                  &lt;a href={`/orders/${order.id}`} className="link-button"&gt;
                    Ver detalle
                  &lt;/a&gt;
                &lt;/td&gt;
              &lt;/tr&gt;
            ))}
          &lt;/tbody&gt;
        &lt;/table&gt;
      )}

      &lt;style&gt;{`
        .orders-container {
          padding: 20px;
          max-width: 1200px;
          margin: 0 auto;
        }

        .filters {
          margin: 20px 0;
          display: flex;
          gap: 10px;
        }

        .search-input,
        .filter-select {
          padding: 8px;
          border: 1px solid #ddd;
          border-radius: 4px;
          font-size: 14px;
        }

        .orders-table {
          width: 100%;
          border-collapse: collapse;
          margin-top: 20px;
        }

        .orders-table th {
          background-color: #ecf0f1;
          padding: 12px;
          text-align: left;
          border-bottom: 2px solid #bdc3c7;
        }

        .orders-table td {
          padding: 12px;
          border-bottom: 1px solid #ecf0f1;
        }

        .status-badge {
          color: white;
          padding: 4px 8px;
          border-radius: 4px;
          font-size: 12px;
          font-weight: bold;
        }

        .order-number {
          font-weight: bold;
          color: #3498db;
        }

        .link-button {
          color: #3498db;
          text-decoration: none;
          padding: 4px 8px;
          border: 1px solid #3498db;
          border-radius: 4px;
          display: inline-block;
        }

        .link-button:hover {
          background-color: #3498db;
          color: white;
        }

        .no-orders {
          text-align: center;
          padding: 40px;
          color: #7f8c8d;
        }
      `}&lt;/style&gt;
    &lt;/div&gt;
  );
};

3.4 3. Ver Detalle y Actualizar Estado
// src/hooks/useOrderDetail.ts
import { useEffect, useState } from 'react';
import ordersApi from '../api/ordersApi';

export interface OrderDetail {
  id: number;
  numero_pedido: string;
  cliente_nombre: string;
  cliente_email: string;
  estado: string;
  tipo_entrega: string;
  subtotal: string;
  impuesto: string;
  total: string;
  fecha_creacion: string;
  detalles: Array&lt;{
    id: number;
    producto: number;
    nombre_producto: string;
    cantidad: number;
    precio_unitario: string;
    subtotal: string;
  }&gt;;
}

export const useOrderDetail = (orderId: number) =&gt; {
  const [order, setOrder] = useState&lt;OrderDetail | null&gt;(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState&lt;string | null&gt;(null);

  useEffect(() =&gt; {
    const fetchOrder = async () =&gt; {
      try {
        const response = await ordersApi.get(`${orderId}/`);
        setOrder(response.data);
      } catch (err: any) {
        setError(
          err.response?.data?.detail ||
          'Error al cargar la orden'
        );
      } finally {
        setLoading(false);
      }
    };

    fetchOrder();
  }, [orderId]);

  const updateStatus = async (newEstado: string) =&gt; {
    try {
      const response = await ordersApi.put(`${orderId}/`, {
        estado: newEstado,
      });
      setOrder(response.data);
      return response.data;
    } catch (err: any) {
      const errorMsg =
        err.response?.data?.estado?.[0] ||
        err.response?.data?.detail ||
        'Error al actualizar estado';
      throw new Error(errorMsg);
    }
  };

  return { order, loading, error, updateStatus };
};

3.4.1 Component: Detalle de Orden
// src/components/OrderDetail.tsx
import React, { useState } from 'react';
import { useOrderDetail } from '../hooks/useOrderDetail';

interface OrderDetailProps {
  orderId: number;
  isAdmin?: boolean;
}

export const OrderDetail: React.FC&lt;OrderDetailProps&gt; = ({
  orderId,
  isAdmin = false,
}) =&gt; {
  const { order, loading, error, updateStatus } = useOrderDetail(orderId);
  const [updating, setUpdating] = useState(false);
  const [updateError, setUpdateError] = useState&lt;string | null&gt;(null);

  if (loading) return &lt;div className="loading"&gt;Cargando detalle...&lt;/div&gt;;
  if (error) return &lt;div className="error"&gt;{error}&lt;/div&gt;;
  if (!order) return &lt;div className="not-found"&gt;Orden no encontrada&lt;/div&gt;;

  const handleStateChange = async (newEstado: string) =&gt; {
    setUpdating(true);
    setUpdateError(null);

    try {
      await updateStatus(newEstado);
    } catch (err: any) {
      setUpdateError(err.message);
    } finally {
      setUpdating(false);
    }
  };

  const allowedTransitions: Record&lt;string, string[]&gt; = {
    RECIBIDO: ['PREPARACION', 'CANCELADO'],
    PREPARACION: ['LISTO', 'CANCELADO'],
    LISTO: ['ENTREGADO', 'CANCELADO'],
    ENTREGADO: ['CANCELADO'],
    CANCELADO: [],
  };

  const nextStates = allowedTransitions[order.estado] || [];

  return (
    &lt;div className="order-detail"&gt;
      &lt;div className="order-header"&gt;
        &lt;h2&gt;Orden {order.numero_pedido}&lt;/h2&gt;
        &lt;p className="cliente-info"&gt;Cliente: {order.cliente_nombre}&lt;/p&gt;
      &lt;/div&gt;

      &lt;div className="order-info-grid"&gt;
        &lt;div className="info-item"&gt;
          &lt;strong&gt;Estado:&lt;/strong&gt;
          &lt;span className="estado-badge"&gt;{order.estado}&lt;/span&gt;
        &lt;/div&gt;
        &lt;div className="info-item"&gt;
          &lt;strong&gt;Tipo Entrega:&lt;/strong&gt;
          &lt;span&gt;{order.tipo_entrega}&lt;/span&gt;
        &lt;/div&gt;
        &lt;div className="info-item"&gt;
          &lt;strong&gt;Fecha Creación:&lt;/strong&gt;
          &lt;span&gt;{new Date(order.fecha_creacion).toLocaleString()}&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;

      {isAdmin && nextStates.length &gt; 0 && (
        &lt;div className="state-transition"&gt;
          &lt;h3&gt;Cambiar Estado&lt;/h3&gt;
          {updateError && &lt;div className="error"&gt;{updateError}&lt;/div&gt;}
          &lt;div className="button-group"&gt;
            {nextStates.map((nextState) =&gt; (
              &lt;button
                key={nextState}
                onClick={() =&gt; handleStateChange(nextState)}
                disabled={updating}
                className={`state-button state-${nextState.toLowerCase()}`}
              &gt;
                {updating ? 'Actualizando...' : nextState}
              &lt;/button&gt;
            ))}
          &lt;/div&gt;
        &lt;/div&gt;
      )}

      &lt;div className="items-section"&gt;
        &lt;h3&gt;Items&lt;/h3&gt;
        &lt;table className="items-table"&gt;
          &lt;thead&gt;
            &lt;tr&gt;
              &lt;th&gt;Producto&lt;/th&gt;
              &lt;th&gt;Cantidad&lt;/th&gt;
              &lt;th&gt;Precio Unitario&lt;/th&gt;
              &lt;th&gt;Subtotal&lt;/th&gt;
            &lt;/tr&gt;
          &lt;/thead&gt;
          &lt;tbody&gt;
            {order.detalles.map((item) =&gt; (
              &lt;tr key={item.id}&gt;
                &lt;td&gt;{item.nombre_producto}&lt;/td&gt;
                &lt;td&gt;{item.cantidad}&lt;/td&gt;
                &lt;td&gt;${parseFloat(item.precio_unitario).toFixed(2)}&lt;/td&gt;
                &lt;td&gt;${parseFloat(item.subtotal).toFixed(2)}&lt;/td&gt;
              &lt;/tr&gt;
            ))}
          &lt;/tbody&gt;
        &lt;/table&gt;
      &lt;/div&gt;

      &lt;div className="totals-section"&gt;
        &lt;div className="total-line"&gt;
          &lt;span&gt;Subtotal:&lt;/span&gt;
          &lt;span&gt;${parseFloat(order.subtotal).toFixed(2)}&lt;/span&gt;
        &lt;/div&gt;
        &lt;div className="total-line"&gt;
          &lt;span&gt;IVA (12%):&lt;/span&gt;
          &lt;span&gt;${parseFloat(order.impuesto).toFixed(2)}&lt;/span&gt;
        &lt;/div&gt;
        &lt;div className="total-line total"&gt;
          &lt;span&gt;Total:&lt;/span&gt;
          &lt;span&gt;${parseFloat(order.total).toFixed(2)}&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;

      &lt;style&gt;{`
        .order-detail {
          padding: 20px;
          max-width: 900px;
          margin: 0 auto;
        }

        .order-header {
          border-bottom: 2px solid #ecf0f1;
          margin-bottom: 20px;
          padding-bottom: 10px;
        }

        .order-header h2 {
          margin: 0;
          color: #2c3e50;
        }

        .cliente-info {
          color: #7f8c8d;
          margin: 5px 0 0 0;
        }

        .order-info-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
          gap: 20px;
          margin: 20px 0;
        }

        .info-item {
          padding: 10px;
          background: #ecf0f1;
          border-radius: 4px;
        }

        .info-item strong {
          display: block;
          margin-bottom: 5px;
          color: #2c3e50;
        }

        .estado-badge {
          padding: 4px 8px;
          border-radius: 4px;
          background: #3498db;
          color: white;
          font-weight: bold;
        }

        .state-transition {
          background: #f9f9f9;
          padding: 15px;
          border-radius: 4px;
          margin: 20px 0;
          border-left: 4px solid #f39c12;
        }

        .button-group {
          display: flex;
          gap: 10px;
          margin-top: 10px;
          flex-wrap: wrap;
        }

        .state-button {
          padding: 8px 16px;
          border: none;
          border-radius: 4px;
          cursor: pointer;
          font-weight: bold;
          transition: opacity 0.3s;
        }

        .state-button:hover:not(:disabled) {
          opacity: 0.8;
        }

        .state-button:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .state-preparacion {
          background: #f39c12;
          color: white;
        }

        .state-listo {
          background: #2ecc71;
          color: white;
        }

        .state-entregado {
          background: #27ae60;
          color: white;
        }

        .state-cancelado {
          background: #e74c3c;
          color: white;
        }

        .items-section {
          margin: 30px 0;
        }

        .items-table {
          width: 100%;
          border-collapse: collapse;
        }

        .items-table th {
          background: #ecf0f1;
          padding: 10px;
          text-align: left;
          border-bottom: 2px solid #bdc3c7;
        }

        .items-table td {
          padding: 10px;
          border-bottom: 1px solid #ecf0f1;
        }

        .totals-section {
          background: #f9f9f9;
          padding: 15px;
          border-radius: 4px;
          margin-top: 20px;
        }

        .total-line {
          display: flex;
          justify-content: space-between;
          padding: 8px 0;
          border-bottom: 1px solid #ecf0f1;
        }

        .total-line.total {
          font-size: 18px;
          font-weight: bold;
          border-bottom: 2px solid #3498db;
          margin-top: 10px;
          padding-top: 10px;
        }
      `}&lt;/style&gt;
    &lt;/div&gt;
  );
};

6.1 Índices de Base de Datos
-- Cliente + Estado (filtrado rápido)
CREATE INDEX idx_pedido_cliente_estado 
ON tienda_pedido (cliente_id, estado);

-- Número de pedido (búsqueda)
CREATE INDEX idx_pedido_numero 
ON tienda_pedido (numero_pedido);

-- Estado + Fecha (listado ordenado)
CREATE INDEX idx_pedido_estado_fecha 
ON tienda_pedido (estado, fecha_creacion DESC);

6.2 Queries Optimizadas
# Evitar N+1 queries
orders = Pedido.objects.select_related(
    'cliente'
).prefetch_related(
    'detalles_venta__producto'
).filter(
    cliente=request.user
).order_by('-fecha_creacion')

El catálogo de productos es el módulo central de TiendaUniversitaria que permite:

Consulta Pública: Estudiantes y visitantes pueden ver productos disponibles
Filtrado y Búsqueda: Encontrar productos por categoría, precio, nombre
Gestión (Admin): Crear, actualizar y eliminar productos
Paginación Automática: 10 productos por página




✅ Lectura Pública (GET sin autenticación)
✅ Escritura Autenticada (POST/PUT/DELETE requieren login)
✅ Filtrado por categoría, precio, estado activo
✅ Búsqueda en nombre y descripción
✅ Ordenamiento por precio, nombre, fecha
✅ Paginación automática (10 items/página)
✅ Imágenes con URLs externas
✅ Validación de stock y precio








