// src/services/productService.ts
import apiClient from './api';

export const getProducts = async (filters = {}) =&gt; {
  const params = new URLSearchParams(filters);
  const response = await apiClient.get(`/productos/?${params}`);
  return response.data;
};

// src/pages/CatalogPage.tsx
import { useState, useEffect } from 'react';
import { getProducts } from '../services/productService';

export const CatalogPage = () =&gt; {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    categoria: '',
    search: '',
    ordering: 'nombre',
    page: 1
  });

  useEffect(() =&gt; {
    const fetchProducts = async () =&gt; {
      try {
        setLoading(true);
        const data = await getProducts(filters);
        setProducts(data.results);
      } catch (error) {
        console.error('Error fetching products:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, [filters]);

  if (loading) return &lt;div&gt;Cargando...&lt;/div&gt;;

  return (
    &lt;div&gt;
      &lt;h1&gt;Catálogo de Productos&lt;/h1&gt;

      &lt;div className="filters"&gt;
        &lt;select 
          value={filters.categoria} 
          onChange={(e) =&gt; setFilters({...filters, categoria: e.target.value})}
        &gt;
          &lt;option value=""&gt;Todas las categorías&lt;/option&gt;
          &lt;option value="TEXTIL"&gt;Textil&lt;/option&gt;
          &lt;option value="INSTITUCIONAL"&gt;Institucional&lt;/option&gt;
        &lt;/select&gt;

        &lt;input 
          type="text" 
          placeholder="Buscar..."
          value={filters.search}
          onChange={(e) =&gt; setFilters({...filters, search: e.target.value})}
        /&gt;
      &lt;/div&gt;

      &lt;div className="products-grid"&gt;
        {products.map(product =&gt; (
          &lt;div key={product.id} className="product-card"&gt;
            &lt;img src={product.imagen_url} alt={product.nombre} /&gt;
            &lt;h3&gt;{product.nombre}&lt;/h3&gt;
            &lt;p&gt;{product.descripcion}&lt;/p&gt;
            &lt;p className="price"&gt;${product.precio}&lt;/p&gt;
            &lt;p className="stock"&gt;Stock: {product.stock}&lt;/p&gt;
            &lt;button&gt;Agregar al carrito&lt;/button&gt;
          &lt;/div&gt;
        ))}
      &lt;/div&gt;
    &lt;/div&gt;
  );
};



export const getProductDetail = async (id) =&gt; {
  const response = await apiClient.get(`/productos/${id}/`);
  return response.data;
};

// Uso en componente
const ProductDetailPage = ({ productId }) =&gt; {
  const [product, setProduct] = useState(null);

  useEffect(() =&gt; {
    getProductDetail(productId).then(setProduct);
  }, [productId]);

  if (!product) return &lt;div&gt;Producto no encontrado&lt;/div&gt;;

  return (
    &lt;div className="product-detail"&gt;
      &lt;img src={product.imagen_url} alt={product.nombre} /&gt;
      &lt;h1&gt;{product.nombre}&lt;/h1&gt;
      &lt;p&gt;{product.descripcion}&lt;/p&gt;
      &lt;p&gt;Precio: ${product.precio}&lt;/p&gt;
      &lt;p&gt;Stock disponible: {product.stock}&lt;/p&gt;
      {product.vencimiento && &lt;p&gt;Vence: {product.vencimiento}&lt;/p&gt;}
    &lt;/div&gt;
  );
};



export const createProduct = async (productData) =&gt; {
  const response = await apiClient.post('/productos/', productData);
  return response.data;
};

// Uso en formulario
const CreateProductForm = () =&gt; {
  const [formData, setFormData] = useState({
    codigo: '',
    nombre: '',
    descripcion: '',
    precio: '',
    stock: '',
    categoria: 'SOUVENIR'
  });

  const handleSubmit = async (e) =&gt; {
    e.preventDefault();
    try {
      const newProduct = await createProduct(formData);
      alert('Producto creado: ' + newProduct.nombre);
    } catch (error) {
      alert('Error: ' + error.response.data.nombre[0]);
    }
  };

  return (
    &lt;form onSubmit={handleSubmit}&gt;
      &lt;input 
        name="nombre" 
        placeholder="Nombre"
        required
      /&gt;
      &lt;textarea 
        name="descripcion" 
        placeholder="Descripción"
      /&gt;
      &lt;input 
        name="precio" 
        type="number" 
        step="0.01"
        placeholder="Precio"
        required
      /&gt;
      &lt;input 
        name="stock" 
        type="number" 
        placeholder="Stock"
        required
      /&gt;
      &lt;button type="submit"&gt;Crear Producto&lt;/button&gt;
    &lt;/form&gt;
  );
};



export const updateProduct = async (id, productData) =&gt; {
  const response = await apiClient.put(`/productos/${id}/`, productData);
  return response.data;
};



export const deleteProduct = async (id) =&gt; {
  await apiClient.delete(`/productos/${id}/`);
};

// Uso
const deleteHandler = async (productId) =&gt; {
  if (window.confirm('¿Está seguro?')) {
    await deleteProduct(productId);
    alert('Producto eliminado');
  }
};







// Componente reutilizable para manejo de errores
const withErrorHandling = (apiCall) =&gt; {
  try {
    return await apiCall();
  } catch (error) {
    switch (error.response?.status) {
      case 400:
        throw new Error('Datos inválidos: ' + Object.values(error.response.data).flat().join(', '));
      case 401:
        throw new Error('No autenticado. Inicie sesión.');
      case 403:
        throw new Error('No tiene permisos para esta acción.');
      case 404:
        throw new Error('Producto no encontrado.');
      default:
        throw new Error('Error del servidor. Intente más tarde.');
    }
  }
};








